        "â": {"item": "ds-cell-sign", "props": {"face": "s", "label": "KENNEL B", "status": "CONTAINED", "text": "GRINNERS\nRELEASE: ON THE TRIAL SYSTEM’S SIGNAL"}},
        "ã": {"item": "ds-jumpsuits", "props": {"face": "n", "text": "Orange jumpsuits on a rail, SUBJECT stencilled across the back of every one. Small, medium, large. One of them is your size, and it has your name on a strip of tape at the collar."}},
