        "è": {"enemy": "ds-ridden", "props": {"faction": "specimen", "coat": "#e0702a", "skin": "#c49a7a", "hair": "#2a1a10", "name": "Trial 11"}, "tag": "labC3"},
        "é": {"enemy": "ds-rat", "props": {"faction": "specimen"}, "tag": "labC4"},
        "ê": {"enemy": "ds-captive", "props": {"faction": "dormant", "key": "Ostrowski", "name": "Hal Ostrowski", "coat": "#e0702a", "skin": "#e0c0a0", "hair": "#6a6a6a", "saved": "Ostrowski. Receiving. I sign for the night deliveries.\n\nTonight I signed for myself. They put my name on the manifest, and I signed it, because you sign what’s on the clipboard.\n\nFour a week, no donor named. I never looked in the crates. I never looked.", "body": "Hal Ostrowski, Receiving. A clipboard in his jumpsuit pocket: tonight’s delivery manifest. The last line is his own name."}, "tag": "ostrowski"},
        "ë": {"item": "ds-console", "props": {"dir": "w", "title": "Cage 8 · release", "kicker": "Cage Lab", "flag": "freeOstrowski", "prompt": "Open cage 8", "text": "CAGE 8 · STOCK: STAFF (1)\nRESERVED: TRIAL 15\n\nRELEASE: CONFIRMED\n\nThe gate of cage 8 slides back. The man inside looks at you as though you might be the next thing."}},
        "ì": {"item": "ds-cell-sign", "props": {"face": "s", "label": "CAGE 1", "status": "CONTAINED", "text": "STOCK: GRINNER (×2)\nTEMPLATE: G. MOSS\nFED: NO (TRIAL STOCK IS NOT FED)"}},
        "í": {"item": "ds-cell-sign", "props": {"face": "s", "label": "CAGE 2", "status": "CONTAINED", "text": "STOCK: MIDWIFE (ADULT)\nFROM: GESTATION (FLOOR 3)\nFOR: TRIAL 12"}},
