        "ï": {"item": "ds-cell-sign", "props": {"face": "n", "label": "CAGE 5", "status": "CONTAINED", "text": "STOCK: SUBJECT, TRIAL 11 (RIDDEN)\nFROM: GESTATION (FLOOR 3)\n\nIt was a contestant once. It still wears the jumpsuit."}},
        "ð": {"item": "ds-cell-sign", "props": {"face": "n", "label": "CAGE 8", "status": "CONTAINED", "text": "STOCK: STAFF (1)\nRESERVED: TRIAL 15\n\nA man in an orange jumpsuit, sitting with his back to the bars. The release is on the console by the far wall."}},
        "ñ": {"item": "ds-specimen-file", "props": {"dir": "s", "title": "Trial stock · log", "kicker": "Cage Lab", "flags": ["fileTrials", "sawProject"], "text": "PROVING GROUNDS · TRIAL STOCK\n\nTRIAL 11 · subject: volunteer (staff) · opponent: Tenant · 41 seconds · subject retained as stock (cage 5)\nTRIAL 12 · subject: volunteer (staff) · opponent: Midwife · 2 min 10 · the board stayed for the hatching\nTRIAL 13 · subject: volunteer (donor) · opponent: Grinners (3) · 19 seconds\nTRIAL 14 · subject: T. LARK · opponent: the Run · IN PROGRESS\n\nVolunteers are drawn from staff and donors. Durations are measured in seconds.", "ariadne": "THE VOLUNTEERS ARE THE DONORS. I HAVE THEIR NAMES."}},
        "ò": {"item": "ds-lab-bench", "props": {"dir": "s", "w": 2, "kit": "rack", "title": "A lab bench", "kicker": "Cage Lab", "text": "Muzzles, collars, a box of tranquilliser darts (empty), and a clipboard: a feeding chart for the Grinners with every box ticked “NO”."}},
        "ó": {"item": "ds-lab-bench", "props": {"dir": "s", "w": 2, "title": "A lab bench", "kicker": "Cage Lab", "text": "A dissecting tray with a Grinner’s jaw on it, wired open. The teeth are human: adult, permanent, every one a different person’s."}},
